export const frequencyWords: (NounCard | VocabCard)[] = rows.map(
  ([id, frequencyRank, word, article, translation, partOfSpeech, icon, exampleDe, exampleEn, plural]) => {
    const base = {
      id,
      topicIds: ['wortschatz-1000'],
      image: { kind: 'icon' as const, icon: `category-${icon}` as IconName },
      frequencyRank,
      source: 'frequency-list' as const,
      ...(exampleDe ? { example: { de: exampleDe, en: exampleEn } } : {}),
      word,
      translation,
    };
    return article
      ? { ...base, type: 'noun' as const, partOfSpeech: 'noun' as const, article, ...(plural ? { plural } : {}) }
      : { ...base, type: 'vocab' as const, partOfSpeech };
  },
);
